        "sample_testcases": [{"input":"CREATE TABLE bases (\n    base_id INT,\n    base_name VARCHAR(20),\n    location VARCHAR(10)\n);\n\nCREATE TABLE survivors (\n    survivor_id INT,\n    base_id INT,\n    supply_count INT\n);\nINSERT INTO bases (base_id, base_name, location) VALUES\n(1, 'Base Alpha', 'Downtown'),\n(2, 'Base Bravo', 'Suburbs'),\n(3, 'Base Charlie', 'Rural'),\n(4, 'Base Delta', 'Downtown');\nINSERT INTO survivors (survivor_id, base_id, supply_count) VALUES\n(1, 1, 4),\n(2, 1, 5),\n(3, 1, 3),\n(4, 2, 6),\n(5, 2, 1),\n(6, 3, 10),\n(7, 3, 7),\n(8, 4, 2),\n(9, 4, 1);","output":"base_name\ttotal_supplies\tsurvivor_count\nBase Alpha\t12\t3\n","explanation":"<p><strong>bases:&nbsp;</strong></p>\n<table>\n<tbody>\n<tr>\n<td>\n<p><strong>base_id</strong></p>\n</td>\n<td>\n<p><strong>base_name</strong></p>\n</td>\n<td>\n<p><strong>location</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>1</strong></p>\n</td>\n<td>\n<p><strong>Base Alpha</strong></p>\n</td>\n<td>\n<p><strong>Downtown</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2</strong></p>\n</td>\n<td>\n<p><strong>Base Bravo</strong></p>\n</td>\n<td>\n<p><strong>Suburbs</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>3</strong></p>\n</td>\n<td>\n<p><strong>Base Charlie</strong></p>\n</td>\n<td>\n<p><strong>Rural</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>4</strong></p>\n</td>\n<td>\n<p><strong>Base Delta</strong></p>\n</td>\n<td>\n<p><strong>Downtown</strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<p><strong>survivors:&nbsp;</strong></p>\n<table>\n<tbody>\n<tr>\n<td>\n<p><strong>survivor_id</strong></p>\n</td>\n<td>\n<p><strong>base_id</strong></p>\n</td>\n<td>\n<p><strong>supply_count</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>1</strong></p>\n</td>\n<td>\n<p><strong>1</strong></p>\n</td>\n<td>\n<p><strong>4</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2</strong></p>\n</td>\n<td>\n<p><strong>1</strong></p>\n</td>\n<td>\n<p><strong>5</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>3</strong></p>\n</td>\n<td>\n<p><strong>1</strong></p>\n</td>\n<td>\n<p><strong>3</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>4</strong></p>\n</td>\n<td>\n<p><strong>2</strong></p>\n</td>\n<td>\n<p><strong>6</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>5</strong></p>\n</td>\n<td>\n<p><strong>2</strong></p>\n</td>\n<td>\n<p><strong>1</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>6</strong></p>\n</td>\n<td>\n<p><strong>3</strong></p>\n</td>\n<td>\n<p><strong>10</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>7</strong></p>\n</td>\n<td>\n<p><strong>3</strong></p>\n</td>\n<td>\n<p><strong>7</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>8</strong></p>\n</td>\n<td>\n<p><strong>4</strong></p>\n</td>\n<td>\n<p><strong>2</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>9</strong></p>\n</td>\n<td>\n<p><strong>4</strong></p>\n</td>\n<td>\n<p><strong>1</strong></p>\n</td>\n</tr>\n</tbody>\n</table>"},{"input":"CREATE TABLE bases (base_id INT, base_name VARCHAR(20), location VARCHAR(10));\nINSERT INTO bases VALUES \n(101, 'Haven', 'Downtown'),\n(102, 'Sanctuary', 'Suburbs'),\n(103, 'Stronghold', 'Rural'),\n(104, 'Outpost', 'Wasteland');\nCREATE TABLE survivors (survivor_id INT, base_id INT, supply_count INT);\nINSERT INTO survivors VALUES \n(2001, 101, 3),\n(2002, 101, 6),\n(2003, 101, 7),\n(2004, 101, 5),\n(2005, 101, 18),\n(2006, 102, 12),\n(2007, 102, 24),\n(2008, 102, 14),\n(2009, 103, 52);","output":"base_name\ttotal_supplies\tsurvivor_count\nHaven\t39\t5\nSanctuary\t50\t3\nStronghold\t52\t1\n","explanation":"<p><strong>bases:&nbsp;</strong></p>\n<table>\n<tbody>\n<tr>\n<td>\n<p><strong>base_id</strong></p>\n</td>\n<td>\n<p><strong>base_name</strong></p>\n</td>\n<td>\n<p><strong>location</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>101</strong></p>\n</td>\n<td>\n<p><strong>Haven</strong></p>\n</td>\n<td>\n<p><strong>Downtown</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>102</strong></p>\n</td>\n<td>\n<p><strong>Sanctuary</strong></p>\n</td>\n<td>\n<p><strong>Suburbs</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>103</strong></p>\n</td>\n<td>\n<p><strong>Stronghold</strong></p>\n</td>\n<td>\n<p><strong>Rural</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>104</strong></p>\n</td>\n<td>\n<p><strong>Outpost</strong></p>\n</td>\n<td>\n<p><strong>Wasteland</strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n<p><strong>survivors:&nbsp;</strong></p>\n<table>\n<tbody>\n<tr>\n<td>\n<p><strong>survivor_id</strong></p>\n</td>\n<td>\n<p><strong>base_id</strong></p>\n</td>\n<td>\n<p><strong>supply_count</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2001</strong></p>\n</td>\n<td>\n<p><strong>101</strong></p>\n</td>\n<td>\n<p><strong>3</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2002</strong></p>\n</td>\n<td>\n<p><strong>101</strong></p>\n</td>\n<td>\n<p><strong>6</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2003</strong></p>\n</td>\n<td>\n<p><strong>101</strong></p>\n</td>\n<td>\n<p><strong>7</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2004</strong></p>\n</td>\n<td>\n<p><strong>101</strong></p>\n</td>\n<td>\n<p><strong>5</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2005</strong></p>\n</td>\n<td>\n<p><strong>101</strong></p>\n</td>\n<td>\n<p><strong>18</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2006</strong></p>\n</td>\n<td>\n<p><strong>102</strong></p>\n</td>\n<td>\n<p><strong>12</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2007</strong></p>\n</td>\n<td>\n<p><strong>102</strong></p>\n</td>\n<td>\n<p><strong>24</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2008</strong></p>\n</td>\n<td>\n<p><strong>102</strong></p>\n</td>\n<td>\n<p><strong>14</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2009</strong></p>\n</td>\n<td>\n<p><strong>103</strong></p>\n</td>\n<td>\n<p><strong>52</strong></p>\n</td>\n</tr>\n</tbody>\n</table>"}]
